package com.kdt.mcgui;
import android.animation.ValueAnimator;import android.content.Context;import android.graphics.*;import android.util.AttributeSet;import android.view.animation.LinearInterpolator;import android.widget.ProgressBar;import androidx.annotation.Nullable;
/** Segmented data-assembly rail used by the original global Download Console. */
public class DownloadAssemblyBar extends ProgressBar{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private ValueAnimator scan;private float phase;public DownloadAssemblyBar(Context c){this(c,null);}public DownloadAssemblyBar(Context c,@Nullable AttributeSet a){super(c,a);setWillNotDraw(false);scan=ValueAnimator.ofFloat(0,1);scan.setDuration(1450);scan.setRepeatCount(-1);scan.setInterpolator(new LinearInterpolator());scan.addUpdateListener(v->{phase=(float)v.getAnimatedValue();invalidate();});}@Override protected void onAttachedToWindow(){super.onAttachedToWindow();if(!scan.isStarted())scan.start();}@Override protected void onDetachedFromWindow(){scan.cancel();super.onDetachedFromWindow();}@Override protected synchronized void onDraw(Canvas c){float w=getWidth(),h=getHeight(),gap=dp(3),segments=14,sw=(w-gap*(segments-1))/segments,done=getProgress()/100f;p.setStyle(Paint.Style.FILL);for(int i=0;i<segments;i++){float l=i*(sw+gap),r=l+sw;float threshold=(i+1)/segments;p.setColor(threshold<=done?0xffdfe4e8:0xff303842);c.drawRoundRect(l,dp(2),r,h-dp(2),dp(2),dp(2),p);}float x=w*phase;p.setShader(new LinearGradient(x-dp(36),0,x+dp(14),0,0x00ffffff,0xffffffff,Shader.TileMode.CLAMP));c.drawRect(Math.max(0,x-dp(38)),0,Math.min(w,x+dp(16)),h,p);p.setShader(null);p.setColor(0x5522c9cb);float lead=w*done;c.drawRect(Math.max(0,lead-dp(2)),0,Math.min(w,lead+dp(2)),h,p);}private float dp(float n){return n*getResources().getDisplayMetrics().density;}}
